const jid = $('Montar entrada').first().json.jid;
let t = ($input.first().json.output || '').trim();
// Prompt: se o áudio respondeu tudo, a IA não escreve nada. Áudio enviado + resposta vazia = não manda balão
// (sem isso cairia na mensagem de erro lá embaixo). [SEM TEXTO] também vale, se a IA usar.
const passos = $input.first().json.intermediateSteps || [];
const audioEnviado = passos.some(p => p.action?.tool === 'enviar_audio' && /ÁUDIO ENVIADO/.test(JSON.stringify(p.observation || '')));
const semTexto = /\[SEM TEXTO\]/i.test(t);
t = t.replace(/\[SEM TEXTO\]/gi, '').trim();
if ((audioEnviado || semTexto) && !t.replace(/\[\d{1,2}\]/g, '').replace(/[\s😊😉.!]/gu, '')) return [{ json: { jid, semTexto: true } }];
// --- numa linha = a IA quer outra mensagem a partir dali (ver COMO A RESPOSTA CHEGA NO WHATSAPP)
t = t.replace(/\n?[ \t]*-{3,}[ \t]*(\n|$)/g, '\n\n§§\n\n');
// Cumprimento (pedido do Victor, 26/10): devolve o MESMO que a cliente usou ('Boa tarde' às 17h59 → 'Boa tarde',
// não 'Boa noite' porque o relógio virou); se ela não cumprimentou, vale a hora do salão.
const hSalao = $now.setZone('America/Cuiaba').hour;
const dela = (String($('Montar entrada').first().json.texto_cliente || '').match(/bom dia|boa tarde|boa noite/gi) || []).pop();
const cumprimento = dela ? dela.toLowerCase() : hSalao < 12 ? 'bom dia' : hSalao < 18 ? 'boa tarde' : 'boa noite';
t = t.replace(/^(\s*(?:(?:oi|olá)[^.!?\n]{0,25}[!,.]\s*)?)(bom dia|boa tarde|boa noite)/i, (m, antes, g) => antes + (g[0] === g[0].toUpperCase() ? cumprimento[0].toUpperCase() + cumprimento.slice(1) : cumprimento));
// Cumprimenta UMA vez: se a IA já respondeu esta cliente nas últimas 3 h, tira o 'Oi, Victor! Boa tarde.' / 'Boa noite!' do
// começo (26/10: 'Boa tarde' e o áudio 30 s depois viraram duas respostas, cada uma com cumprimento)
const jaFalou = ($('Sobre esta cliente').first().json.texto || '').match(/Você já conversou com ela hoje \(sua última resposta foi às (\d\d):(\d\d)/);
if (jaFalou) {
  const ultima = $now.setZone('America/Cuiaba').set({ hour: +jaFalou[1], minute: +jaFalou[2] });
  if ($now.diff(ultima, 'hours').hours < 3) {
    const semOi = t.replace(/^\s*(?:(?:oi|olá)(?:,\s*[^.!?\n]{1,25})?[!.,]\s*)?(?:(?:bom dia|boa tarde|boa noite)(?:,\s*[^.!?\n]{1,25})?[!.]\s*)?/i, '').trim();
    if (semOi) t = semOi[0].toUpperCase() + semOi.slice(1);
  }
}
// já conversaram hoje (ficha): tira a reapresentação que a IA às vezes ainda põe ('Sou a assistente virtual da Gleide.')
if (/Você já conversou com ela hoje/.test($('Sobre esta cliente').first().json.texto || '')) {
  const semApresentacao = t.replace(/(^|[.!?]\s+|\n)\s*((Eu )?sou a assistente virtual( da Gleide)?( Vieira)?|Aqui é a assistente( virtual)?( da Gleide)?)[^.!?\n]*[.!?]?/gi, '$1').trim();
  if (semApresentacao) t = semApresentacao;
}
// sem negrito/markdown: mensagem de gente não tem *asterisco*
t = t.replace(/\*\*(.+?)\*\*/g, '$1').replace(/\*([^*\n]+)\*/g, '$1').replace(/^#+\s*/gm, '').replace(/^\s*[-•]\s+/gm, '');
// frases de robô que a IA às vezes insiste em usar: tira antes de enviar (se sobrar texto)
const semRobo = t.replace(/\s*(como|em que) (posso|eu posso|poderia) (te |lhe )?ajudar( você)?( hoje)?\s*\?/gi, '').replace(/\s*(posso te ajudar|te ajudo) (em|com) (mais )?(algo|alguma coisa)( mais)?\s*\?/gi, '').replace(/, do Toda Bonita Mega Hair/gi, '').trim();
if (semRobo) t = semRobo;
// sobras de chatbot no fim (humanizer §22): fecho automático que não diz nada; só sai se sobrar texto
const semFecho = t.replace(/\s*(fico|ficamos|estou|estamos) (à|a) (sua )?disposi[çc][ãa]o[^.!?\n]*[.!?]?/gi, '').replace(/\s*(qualquer coisa|qualquer d[úu]vida|se precisar|se tiver (alguma|mais alguma) d[úu]vida)[^.!?\n]*(estou|estamos|é só|me (chama|fala|avisa))[^.!?\n]*[.!?]?/gi, '').replace(/\s*espero ter ajudado[.!]?/gi, '').replace(/\s*(e )?estou aqui (pra|para) (te |lhe )?ajudar[.!]?/gi, '').trim();
if (semFecho && semFecho !== t) t = /[.!?😊😉]$/u.test(semFecho) ? semFecho : semFecho + '.';
// palavra de controle das ferramentas ("REMARCADO! Mudei…"): é para a IA, não para a cliente
t = t.replace(/\b(REMARCADO|AGENDADO|CANCELADO|ANOTADO)\b[!.:,]?\s*/g, '').replace(/^\s*([a-zà-ú])/, (m, l) => m.replace(l, l.toUpperCase()));
// regra da Gleide: valor só quando a cliente pergunta preço. Se ela não perguntou, tira as frases com R$
// ou 'o valor depende…' (a IA às vezes solta mesmo assim) e o 'que legal' de robô
const pediuPreco = /(quanto|valor|pre[cç]o|cust|or[cç]amento|caro|barat|cobra|tabela)/i.test($('Montar entrada').first().json.texto_cliente || '');
const FRASES = /(?<=[.!?😊😉🥰])\s+/u;
const QUANDO = /\b\d{1,2}(h|:\d\d)/;
// limpa linha por linha: o quadro da agenda vem uma linha por período e precisa chegar assim
const limpar = (p) => p.split('\n').map(limparLinha).filter(Boolean).join('\n');
const limparLinha = (p) => {
  let fs = p.split(FRASES).filter(f => !/^(ah,? )?que legal\b/i.test(f));
  // frase que também oferece horário ("que fica R$ 450, eu tenho segunda às 13h"): tira só o preço, senão a
  // cliente recebe "algum desses horários?" sem horário nenhum
  if (!pediuPreco) fs = fs.map(f => {
    if (!/R\$\s?\d/.test(f)) return f;
    const s = f.replace(/,?\s*(?:que\s+)?(?:fica|custa|sai|é|está|no valor de|por)?\s*(?:em\s+|por\s+|de\s+)?R\$\s?\d+(?:\.\d{3})*(?:,\d{2})?(?:\s*reais)?/gi, '').replace(/\s+,/g, ',').trim();
    return !/R\$/.test(s) && QUANDO.test(s) ? s : '';
  }).filter(f => f && !/\bvalor\b[^.?!]*\bdepende/i.test(f));
  return fs.join(' ').trim();
};
// [n] = parágrafo que responde a n-ª mensagem seguida dela. Número no meio do texto também abre parágrafo;
// parágrafo sem número continua respondendo a mesma mensagem do anterior
t = t.replace(/\s*\[(\d{1,2})\]\s*/g, '\n\n[$1] ').trim();
let ref = 0;
let paragrafos = t.split(/\n\s*\n/).map(s => { const m = s.trim().match(/^\[(\d{1,2})\]\s*/); if (m) ref = Number(m[1]); return { t: s.trim().slice(m ? m[0].length : 0).trim(), ref }; }).filter(p => p.t);
const limpos = paragrafos.map(p => ({ t: limpar(p.t), ref: p.ref })).filter(p => p.t);
if (limpos.length) paragrafos = limpos;
// Rede de segurança: se a IA falhar e devolver vazio, a cliente não fica sem resposta
const falhou = !paragrafos.some(p => p.t !== '§§'); // o alerta-workflows.js avisa o Victor
if (falhou) paragrafos = [{ t: 'Desculpa, tive um probleminha aqui e não consegui ler sua mensagem. Pode mandar de novo? 😊', ref: 0 }];
// Como gente manda no WhatsApp (pedido do Victor, 26/10): um balão por parágrafo, na ordem, no máximo 2.
// Parágrafo minúsculo (menos de 25 letras, ex.: 'Oi, Maria!') gruda no seguinte; parágrafo enorme (mais de
// 300 letras) é cortado entre frases; se passar de 3, os do fim se juntam no 3º. O --- da IA conta como parágrafo.
const ps = paragrafos.filter(p => p.t !== '§§').map(p => p.t);
let baloes = [];
let junto = '';
for (const p of ps) {
  junto = junto ? junto + '\n\n' + p : p;
  if (junto.length >= 25) { baloes.push({ t: junto, ref: 0 }); junto = ''; }
}
if (junto) { if (baloes.length) baloes[baloes.length - 1].t += '\n\n' + junto; else baloes.push({ t: junto, ref: 0 }); }
const cortar = (t) => {
  if (t.length <= 300 || t.includes('\n')) return [t]; // quadro do dia (em linhas) vai inteiro
  const fs = t.split(FRASES);
  if (fs.length < 2) return [t];
  let a = '', i = 0;
  while (i < fs.length - 1 && (a + ' ' + fs[i]).trim().length < t.length / 2) a = (a + ' ' + fs[i++]).trim();
  if (!a) a = fs[i++];
  return [a, fs.slice(i).join(' ').trim()].filter(Boolean);
};
baloes = baloes.flatMap((b) => cortar(b.t).map((t) => ({ t, ref: 0 })));
// no máximo 2 balões (26/10: 3 balões era texto demais)
if (baloes.length > 2) baloes = [baloes[0], { t: baloes.slice(1).map(b => b.t).join('\n\n'), ref: 0 }];
baloes = baloes.filter(b => b.t);
// Responder citando só quando a mensagem chegou enquanto a IA ainda respondia outra (a resposta sai
// depois de outra e ficaria solta): cita a última mensagem do bloco
let msgs = [];
try { msgs = JSON.parse($('Montar entrada').first().json.mensagens || '[]'); } catch (e) {}
const esperou = $('Aguardar 3s (IA respondendo)').isExecuted;
const citarDe = (b, i) => (esperou && i === 0 && msgs.length ? msgs[msgs.length - 1].id || '' : '');
// Ritmo de gente (pedido do Victor, 25/10): o tempo depende do tamanho do texto.
// pausa = 'lendo e pensando' antes do 'digitando…': 1º balão 1,5-3 s + 20 ms por letra da mensagem dela (até 8 s);
//         balões seguintes 1-2,5 s (respiro entre uma mensagem e outra).
// delay = tempo de 'digitando…': 65-90 ms por letra (uns 12 caracteres por segundo, alguém rápido no celular),
//         no mínimo 2,5 s e no máximo 22 s. Ex.: 40 letras ≈ 3 s; 120 ≈ 9 s; 250 ≈ 19 s.
const ale = (a, b) => a + Math.random() * (b - a);
const lida = ($('Montar entrada').first().json.texto_cliente || '').length;
return baloes.map(({ t: texto, ref }, i) => ({ json: { jid, texto, falhou, citar: citarDe({ ref }, i),
  pausa: Math.round((i === 0 ? Math.min(8, ale(1.5, 3) + lida * 0.02) : ale(1, 2.5)) * 10) / 10,
  delay: Math.round(Math.min(22000, Math.max(2500, texto.length * ale(65, 90)))) } }));

// o tempo de 'digitando…' em blocos iguais de até 7,5 s: cada chamada da Evolution dura o delay do bloco e o
// próximo bloco começa um bloco depois (batchInterval = delay), então o tempo total é o delay calculado
const b = $input.first().json;
const n = Math.max(1, Math.ceil(b.delay / 7500));
const delay = Math.round(b.delay / n);
return Array.from({ length: n }, () => ({ json: { jid: b.jid, delay }, pairedItem: 0 }));

const TZ = 'America/Cuiaba';
const ficha = $('Supabase: ficha da cliente').first().json;
const hist = $('Supabase: histórico da cliente').all().map((i) => i.json).filter((a) => a.inicio);
const dia = (s) => DateTime.fromISO(s).setZone(TZ).setLocale('pt-BR');
const data = (s) => (s.length === 10 ? DateTime.fromISO(s, { zone: TZ }) : dia(s)).toFormat('dd/LL/yyyy');
const NOVA = 'Cliente nova: é a primeira conversa dela com o salão. Nunca veio e não tem nada marcado; trate como primeiro contato.';
// Mensagens dela que ficaram sem resposta (ex.: a IA falhou e só mandou o pedido de desculpas): não estão na
// memória do Redis, mas estão no banco. Sem isso a IA esquece o que ela pediu antes.
let agora_ids = [];
try { agora_ids = JSON.parse($('Montar entrada').first().json.mensagens || '[]').map((m) => m.id).filter(Boolean); } catch (e) {}
const recentes = $('Supabase: últimas mensagens').all().map((i) => i.json).filter((m) => m.direcao);
const pendentes = [];
for (const m of recentes) {
  if (m.direcao !== 'entrada') { if (/^Desculpa, tive um probleminha/.test(m.conteudo || '')) continue; break; } // o pedido de desculpas não responde nada
  if (!agora_ids.includes(m.wa_message_id)) pendentes.unshift(m);
}
const SEM_RESPOSTA = pendentes.length ? '\nMENSAGENS ANTERIORES DELA AINDA SEM RESPOSTA (responda junto com a de agora; podem não estar no histórico): ' +
  pendentes.map((m) => '«' + String(m.conteudo || '').slice(0, 300) + '» (' + dia(m.criado_em).toFormat('HH:mm') + ')').join(' · ') : '';
// Já respondeu nas últimas horas (a memória do Redis pode ter sido perdida ou apagada): não se apresentar de novo
const ultimaIA = recentes.find((m) => m.direcao === 'saida' && !/^Desculpa, tive um probleminha/.test(m.conteudo || ''));
const JA_FALOU = ultimaIA ? '\nVocê já conversou com ela hoje (sua última resposta foi às ' + dia(ultimaIA.criado_em).toFormat('HH:mm') +
  '): continue a conversa, sem se apresentar de novo nem cumprimentar como primeiro contato.' : '';
if (!ficha.id) return [{ json: { texto: (ultimaIA ? '' : NOVA) + JA_FALOU + SEM_RESPOSTA } }];
// A ficha é criada na 1ª mensagem (n8n_registrar_entrada), então "sem visita" sozinho não diz se é nova:
// nova = cadastrada há menos de 1 dia e sem nenhum atendimento (nem marcado nem feito).
const recente = DateTime.fromISO(ficha.criado_em) > DateTime.now().minus({ days: 1 });
if (recente && !ficha.total_visitas && !hist.length) return [{ json: { texto: (ultimaIA ? 'Ainda não veio ao salão e não tem nada marcado.' : NOVA) + (ficha.observacoes ? '\nObservações da Gleide: ' + ficha.observacoes : '') + JA_FALOU + SEM_RESPOSTA } }];

const SITUACAO = { em_dia: 'em dia', retorno_chegando: 'retorno de algum serviço chegando', retorno_atrasado: 'passou da data de voltar e ainda não marcou',
  inativa: 'sumida há bastante tempo', sem_visita: 'já conversou, mas ainda não veio ao salão' };
const linhas = [];
if (ficha.nome) linhas.push('Nome: ' + ficha.nome);
linhas.push('Situação: ' + (SITUACAO[ficha.status] || ficha.status));
if (ficha.total_visitas) linhas.push('Veio ' + ficha.total_visitas + 'x; última visita em ' + data(ficha.ultima_visita) + '.');

const agora = DateTime.now();
const futuros = hist.filter((a) => a.status === 'agendado' && dia(a.inicio) > agora).reverse();
for (const a of futuros) linhas.push('Horário marcado: ' + dia(a.inicio).toFormat("cccc, dd/LL 'às' HH:mm") + ' — ' + (a.servicos?.nome || 'serviço não informado'));

// um por serviço (o mais recente), com o retorno previsto de cada um
const vistos = new Set();
for (const a of hist.filter((x) => x.status === 'realizado')) {
  const nome = a.servicos?.nome || 'serviço não informado';
  if (vistos.has(nome)) continue;
  vistos.add(nome);
  linhas.push('Já fez: ' + nome + ' em ' + data(a.inicio) + (a.retorno_previsto ? ' → voltar por volta de ' + data(a.retorno_previsto) : ''));
}
const faltas = hist.filter((a) => a.status === 'faltou').length;
if (faltas) linhas.push('Faltou ' + faltas + 'x sem avisar.');
if (ficha.observacoes) linhas.push('Observações da Gleide: ' + ficha.observacoes.replace(/\s*\n\s*/g, ' | '));
// a Gleide chamou pelo CRM e esta mensagem é a resposta dela
const alo = $('Supabase: último alô').first().json;
// remarcação: a Gleide teve um imprevisto e pediu pelo app para remarcar um horário (ver CONTRATO.md)
// falta: ela não veio e a IA a chamou sozinha para marcar outro horário (ver supabase/007)
if (alo.mensagem && alo.tipo === 'falta') linhas.push('ALÔ DE FALTA: ela faltou ao horário de ' +
  (alo.horario_original ? dia(alo.horario_original).toFormat("cccc, dd/LL 'às' HH:mm") : 'antes') +
  ' e em ' + dia(alo.criado_em).toFormat("dd/LL 'às' HH:mm") + ' você mandou: «' + alo.mensagem + '». A mensagem de agora é a resposta.');
// atraso: passou do horário dela, ela não chegou e a IA perguntou se está a caminho (ver supabase/011)
else if (alo.mensagem && alo.tipo === 'atraso') linhas.push('ALÔ DE ATRASO: o horário dela era ' +
  (alo.horario_original ? dia(alo.horario_original).toFormat("cccc, dd/LL 'às' HH:mm") + ' (data_hora_inicio = ' + dia(alo.horario_original).toFormat("yyyy-LL-dd'T'HH:mm") + ')' : 'hoje') +
  ', ela não tinha chegado e em ' + dia(alo.criado_em).toFormat("dd/LL 'às' HH:mm") + ' você mandou: «' + alo.mensagem + '». A mensagem de agora é a resposta.' +
  (alo.agendamentos?.status === 'faltou' ? ' ATENÇÃO: ela não respondeu a tempo e esse horário já ficou como falta (pode ter ido para outra cliente).' : ''));
// vaga: abriu um horário antes do dela e a IA ofereceu adiantar (ver supabase/010)
else if (alo.mensagem && alo.tipo === 'vaga') linhas.push('ALÔ DE VAGA: em ' + dia(alo.criado_em).toFormat("dd/LL 'às' HH:mm") +
  ' você ofereceu adiantar o horário dela de ' + (alo.horario_original ? dia(alo.horario_original).toFormat("cccc, dd/LL 'às' HH:mm") : 'agora') +
  ' para a vaga de ' + (alo.vagas?.inicio ? dia(alo.vagas.inicio).toFormat("cccc, dd/LL 'às' HH:mm") + ' (data_hora_nova = ' + dia(alo.vagas.inicio).toFormat("yyyy-LL-dd'T'HH:mm") + ')' : '?') +
  ' e mandou: «' + alo.mensagem + '». A mensagem de agora é a resposta.' +
  // vaga de atraso: confere na hora se a cliente atrasada não apareceu (a rotina de 5 min pode não ter fechado a vaga ainda)
  (alo.vagas && (alo.vagas.status !== 'aberta' || (alo.vagas.motivo === 'atraso' && alo.vagas.agendamentos?.status !== 'faltou'))
    ? ' ATENÇÃO: essa vaga não está mais livre (outra pessoa ficou com ela ou já está em cima da hora).' : ''));
else if (alo.mensagem && alo.tipo === 'remarcacao') linhas.push('ALÔ DE REMARCAÇÃO: em ' + dia(alo.criado_em).toFormat("dd/LL 'às' HH:mm") +
  ' a Gleide pediu para remarcar o horário de ' + (alo.horario_original ? dia(alo.horario_original).toFormat("cccc, dd/LL 'às' HH:mm") : 'ela') +
  ' e mandou: «' + alo.mensagem + '». A mensagem de agora é a resposta a esse pedido.');
// aviso: a Gleide pediu à assistente para avisar a cliente (horário mudado, cancelamento, recado; ver supabase/013)
else if (alo.mensagem && alo.tipo === 'aviso') linhas.push('AVISO DO SALÃO: em ' + dia(alo.criado_em).toFormat("dd/LL 'às' HH:mm") +
  ' a Gleide mandou avisar: «' + alo.mensagem + '». A mensagem de agora pode ser a resposta a esse aviso.');
else if (alo.mensagem) linhas.push('ALÔ DE ' + (alo.tipo === 'reativacao' ? 'REATIVAÇÃO' : 'RETORNO') + ': em ' + dia(alo.criado_em).toFormat("dd/LL 'às' HH:mm") +
  ' a Gleide mandou para ela: «' + alo.mensagem + '». A mensagem de agora é a resposta a esse alô.');
return [{ json: { texto: linhas.join('\n') + JA_FALOU + SEM_RESPOSTA } }];

const catalogo = (($('Supabase: áudios do salão').first().json.config) || {}).audios_prontos || [];
const enviados = $('Supabase: áudios já enviados').all().map((i) => i.json.conteudo || '').join(' ');
if (!catalogo.length) return [{ json: { texto: '(nenhum áudio pronto cadastrado: responda sempre em texto)' } }];
return [{ json: { texto: catalogo.map((a) => '- ' + a.tema + ' — quando usar: ' + (a.quando_usar || a.tema) +
  (enviados.includes('[áudio pronto: ' + a.tema + ']') ? ' (JÁ ENVIADO para esta cliente: não mande de novo)' : '')).join('\n') } }];

const p = JSON.parse($('Pedido: procurar').first().json.pedido);
const resposta = $('Extrair dados').first().json.texto.trim();
const nome = String(p.nome || '').trim().split(/\s+/)[0] || '';
const instrucao = 'Você é a assistente virtual da Gleide, do salão Toda Bonita Mega Hair, conversando pelo WhatsApp com a cliente ' +
  (nome || '') + '. Antes, a cliente perguntou algo que só a Gleide sabia: "' + p.pergunta + '". Você disse que ia confirmar com a Gleide. ' +
  'A Gleide respondeu: "' + resposta + '". Escreva a mensagem para a cliente passando essa resposta, em português do Brasil, ' +
  'curta (1 ou 2 frases), natural e gentil, como uma atendente de verdade. Não invente nada além do que a Gleide disse, ' +
  'não mude o sentido, não use negrito nem listas, no máximo um emoji. Responda só com a mensagem.';
return [{ json: { ...p, nome, resposta, instrucao } }];

const p = $('Pedido: preparar').first().json;
let t = String($input.first().json.candidates?.[0]?.content?.parts?.map((x) => x.text || '').join('') || '').trim();
t = t.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^["“]|["”]$/g, '').trim();
if (!t) t = 'Falei com a Gleide sobre isso: ' + p.resposta;
return [{ json: { ...p, texto: t } }];

// lista do Redis: [0] = mais nova (a memória grava com LPUSH)
const lista = [].concat($input.first().json.memoria || []);
const quebra = (s) => { try { const m = JSON.parse(s); return m.type === 'tool' || (m.type === 'ai' && (m.data?.tool_calls || []).length > 0); } catch (e) { return false; } };
let fim = Math.min(lista.length, 40);
if (!fim || !quebra(lista[fim - 1])) return [{ json: { cortar: false }, pairedItem: 0 }];
// recua até uma mensagem dela: o histórico começa como uma conversa normal
const dela = (s) => { try { return JSON.parse(s).type === 'human'; } catch (e) { return false; } };
while (fim > 0 && !dela(lista[fim - 1])) fim--;
